CREATE TABLE IF NOT EXISTS pub_plans (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,article_id BIGINT UNSIGNED NOT NULL,article_snapshot_id BIGINT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL,schedule_type VARCHAR(32) NOT NULL,scheduled_at DATETIME(6),timezone VARCHAR(64) NOT NULL,failure_policy_json JSON,client_request_id VARCHAR(128) NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_pub_plan_request(enterprise_id,client_request_id),KEY idx_pub_plan_tenant_status(enterprise_id,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pub_tasks (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,publish_plan_id BIGINT UNSIGNED NOT NULL,article_snapshot_id BIGINT UNSIGNED NOT NULL,publish_channel_id BIGINT UNSIGNED NOT NULL,publish_target_id BIGINT UNSIGNED,platform_account_id BIGINT UNSIGNED,execution_mode VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,priority INT NOT NULL DEFAULT 0,scheduled_at DATETIME(6) NOT NULL,next_retry_at DATETIME(6),attempt_count INT UNSIGNED NOT NULL DEFAULT 0,max_attempts INT UNSIGNED NOT NULL DEFAULT 3,current_lease_id BIGINT UNSIGNED,result_url VARCHAR(2048),platform_article_id VARCHAR(255),error_category VARCHAR(64),error_code VARCHAR(64),error_message TEXT,completed_at DATETIME(6),version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_pub_task_claim(status,scheduled_at,priority),KEY idx_pub_task_tenant(enterprise_id,publish_plan_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS geo_monitor_plans (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL,schedule_type VARCHAR(32) NOT NULL,cron_expression VARCHAR(128),timezone VARCHAR(64) NOT NULL,question_ids_json JSON NOT NULL,site_targets_json JSON NOT NULL,next_run_at DATETIME(6),last_run_at DATETIME(6),client_request_id VARCHAR(128) NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_geo_plan_request(enterprise_id,client_request_id),KEY idx_geo_plan_tenant(enterprise_id,status,next_run_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS geo_tasks (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,monitor_plan_id BIGINT UNSIGNED,brand_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,inclusion_site_id BIGINT UNSIGNED NOT NULL,platform_account_id BIGINT UNSIGNED,model_entry VARCHAR(128),locale VARCHAR(32),region VARCHAR(128),status VARCHAR(32) NOT NULL,priority INT NOT NULL DEFAULT 0,scheduled_at DATETIME(6) NOT NULL,attempt_count INT UNSIGNED NOT NULL DEFAULT 0,max_attempts INT UNSIGNED NOT NULL DEFAULT 3,current_lease_id BIGINT UNSIGNED,error_category VARCHAR(64),error_code VARCHAR(64),error_message TEXT,completed_at DATETIME(6),version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_geo_task_claim(status,scheduled_at,priority),KEY idx_geo_task_tenant(enterprise_id,monitor_plan_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS geo_answer_snapshots (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,geo_task_id BIGINT UNSIGNED NOT NULL,attempt_id BIGINT UNSIGNED NOT NULL,inclusion_site_id BIGINT UNSIGNED NOT NULL,model_entry VARCHAR(128),question_text TEXT NOT NULL,answer_text LONGTEXT,answer_status VARCHAR(32) NOT NULL,screenshot_key VARCHAR(1024),evidence_json JSON,session_ref VARCHAR(255),observed_at DATETIME(6) NOT NULL,content_hash CHAR(64) NOT NULL,client_version VARCHAR(64),created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_geo_answer_task(enterprise_id,geo_task_id,observed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS geo_citations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,answer_snapshot_id BIGINT UNSIGNED NOT NULL,url VARCHAR(2048) NOT NULL,domain VARCHAR(255) NOT NULL,title VARCHAR(1024),position INT UNSIGNED NOT NULL DEFAULT 0,is_enterprise_source BOOLEAN NOT NULL DEFAULT FALSE,article_id BIGINT UNSIGNED,metadata_json JSON,created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_geo_citation_answer(enterprise_id,answer_snapshot_id,position),KEY idx_geo_citation_domain(domain)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS geo_mentions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,answer_snapshot_id BIGINT UNSIGNED NOT NULL,entity_type VARCHAR(32) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,text TEXT NOT NULL,position INT UNSIGNED NOT NULL DEFAULT 0,sentiment VARCHAR(32),confidence DECIMAL(6,5) NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_geo_mention_answer(enterprise_id,answer_snapshot_id,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS geo_analysis_results (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,answer_snapshot_id BIGINT UNSIGNED NOT NULL,analysis_version INT UNSIGNED NOT NULL,rule_version VARCHAR(64) NOT NULL,writing_model_id BIGINT UNSIGNED,status VARCHAR(32) NOT NULL,brand_mentioned BOOLEAN NOT NULL DEFAULT FALSE,enterprise_cited BOOLEAN NOT NULL DEFAULT FALSE,visibility_score DECIMAL(8,4) NOT NULL DEFAULT 0,accuracy_score DECIMAL(8,4) NOT NULL DEFAULT 0,confidence DECIMAL(6,5) NOT NULL DEFAULT 0,result_json JSON NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_geo_analysis_version(answer_snapshot_id,analysis_version),KEY idx_geo_analysis_tenant(enterprise_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wrk_nodes (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,node_id VARCHAR(128) NOT NULL,name VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL,approval_status VARCHAR(32) NOT NULL,credential_hash CHAR(64) NOT NULL,client_version VARCHAR(64) NOT NULL,driver_versions_json JSON,capabilities_json JSON NOT NULL,system_info_json JSON,max_concurrency INT UNSIGNED NOT NULL DEFAULT 1,last_heartbeat_at DATETIME(6),revoked_at DATETIME(6),version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_wrk_node_id(node_id),KEY idx_wrk_node_status(status,approval_status,last_heartbeat_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wrk_task_leases (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,task_type VARCHAR(32) NOT NULL,task_id BIGINT UNSIGNED NOT NULL,worker_node_id BIGINT UNSIGNED NOT NULL,lease_token_hash CHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,lease_version BIGINT UNSIGNED NOT NULL DEFAULT 1,leased_at DATETIME(6) NOT NULL,expires_at DATETIME(6) NOT NULL,released_at DATETIME(6),release_reason VARCHAR(255),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_wrk_lease_token(lease_token_hash),KEY idx_wrk_lease_task(task_type,task_id,status),KEY idx_wrk_lease_expiry(status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ops_outbox_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,aggregate_type VARCHAR(64) NOT NULL,aggregate_id VARCHAR(128) NOT NULL,event_type VARCHAR(128) NOT NULL,payload_json JSON NOT NULL,idempotency_key VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL,available_at DATETIME(6) NOT NULL,published_at DATETIME(6),attempt_count INT UNSIGNED NOT NULL DEFAULT 0,last_error TEXT,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_ops_outbox_idempotency(idempotency_key),KEY idx_ops_outbox_delivery(status,available_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ops_audit_logs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED,actor_type VARCHAR(32) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,audience VARCHAR(32) NOT NULL,action VARCHAR(128) NOT NULL,resource_type VARCHAR(64) NOT NULL,resource_id VARCHAR(128) NOT NULL,result VARCHAR(32) NOT NULL,reason VARCHAR(1024),before_json JSON,after_json JSON,ip_address VARCHAR(64),user_agent VARCHAR(512),request_id VARCHAR(128),trace_id VARCHAR(128),created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_ops_audit_actor(actor_type,actor_id,created_at),KEY idx_ops_audit_tenant(enterprise_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
